import "fmt"

// ConnectionMemoryProfile рассчитывает теоретический расход памяти под сетевые соединения
type ConnectionMemoryProfile struct {
	Connections       int
	StackPerConnBytes int
	RuntimeOverhead   int
}

func (p ConnectionMemoryProfile) TotalMemoryMB() float64 {
	totalBytes := p.Connections * (p.StackPerConnBytes + p.RuntimeOverhead)
	return float64(totalBytes) / (1024 * 1024)
}

func main() {
	conns := []int{10_000, 100_000, 500_000, 1_000_000, 10_000_000}

	fmt.Println("=== Анализ потребления памяти: goroutine-per-connection vs Event-Loop ===")
	fmt.Printf("%-12s | %-25s | %-20s\n", "Соединений", "Go net (goroutine-per-conn)", "gnet (Event Loop)")
	fmt.Println("-------------------------------------------------------------------------")

	for _, c := range conns {
		// Go net: 2048 байт минимальный стек + ~1500 байт структуры runtime.g и дескриптор
		goNetMem := ConnectionMemoryProfile{
			Connections:       c,
			StackPerConnBytes: 2048,
			RuntimeOverhead:   1536,
		}.TotalMemoryMB()

		// gnet: нет горутины на соединение! Только запись в epoll и дескриптор сокета (~256 байт)
		gnetMem := ConnectionMemoryProfile{
			Connections:       c,
			StackPerConnBytes: 0,
			RuntimeOverhead:   256,
		}.TotalMemoryMB()

		fmt.Printf("%-12d | %15.2f MB             | %10.2f MB\n", c, goNetMem, gnetMem)
	}
}

package main

import (
	"fmt"
	"io"
	"log"
	"net"
	"net/http"
	_ "net/http/pprof"
	"runtime"
	"sync/atomic"
	"time"
)

var activeConnections int64

func handleConn(c net.Conn) {
	defer func() {
		_ = c.Close()
		atomic.AddInt64(&activeConnections, -1)
	}()

	atomic.AddInt64(&activeConnections, 1)

	// Аллоцируем буфер для чтения
	buf := make([]byte, 1024)
	for {
		// Блокирующий вызов: горутина засыпает в runtime.gopark
		n, err := c.Read(buf)
		if err != nil {
			if err != io.EOF {
				// Ошибка сокета
			}
			return
		}
		// Эхо-ответ
		if _, err := c.Write(buf[:n]); err != nil {
			return
		}
	}
}

func main() {
	// 1. Запуск pprof профилировщика на порту 6060
	go func() {
		log.Println("[pprof] Доступен по адресу: http://localhost:6060/debug/pprof/")
		_ = http.ListenAndServe("127.0.0.1:6060", nil)
	}()

	// 2. Фоновый мониторинг использования памяти
	go func() {
		var m runtime.MemStats
		ticker := time.NewTicker(3 * time.Second)
		defer ticker.Stop()

		for range ticker.C {
			runtime.ReadMemStats(&m)
			fmt.Printf("[METRICS] Соединений: %5d | Горутин: %5d | Память стеков: %6.2f MB | Heap InUse: %6.2f MB\n",
				atomic.LoadInt64(&activeConnections),
				runtime.NumGoroutine(),
				float64(m.StackInuse)/(1024*1024),
				float64(m.HeapInuse)/(1024*1024),
			)
		}
	}()

	// 3. Запуск классического TCP-слушателя
	ln, err := net.Listen("tcp", "127.0.0.1:9011")
	if err != nil {
		log.Fatalf("Listen error: %v", err)
	}
	defer ln.Close()

	log.Println("Классический сервер Go запущен на 127.0.0.1:9011...")
	for {
		conn, err := ln.Accept()
		if err != nil {
			log.Printf("Accept error: %v", err)
			continue
		}
		// Запуск новой горутины на КАЖДОЕ соединение!
		go handleConn(conn)
	}
}

